SELECT id, title, project, pinned, trim(substr(replace(replace(replace(replace(replace(replace(replace(char(10) || substr(body, instr(body || char(10), char(10)) + 1), char(10) || '- [', char(10) || '['), char(10) || '- ', char(10)), char(10), ' '), '[ ] ', '☐ '), '[x] ', '☑ '), '**', ''), '#', ''), 1, 160)) AS snippet, CASE WHEN COALESCE(updated_at, created_at) IS NULL THEN NULL WHEN date((COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') = ?4 THEN strftime('%H:%M', (COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') WHEN date((COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') = date(?4, '-1 day') THEN 'Yesterday' WHEN date((COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') > date(?4, '-7 day') THEN CASE strftime('%w', (COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') WHEN '0' THEN 'Sun' WHEN '1' THEN 'Mon' WHEN '2' THEN 'Tue' WHEN '3' THEN 'Wed' WHEN '4' THEN 'Thu' WHEN '5' THEN 'Fri' ELSE 'Sat' END ELSE CAST(strftime('%d', (COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') AS INTEGER) || ' ' || substr('JanFebMarAprMayJunJulAugSepOctNovDec', (CAST(strftime('%m', (COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch') AS INTEGER) - 1) * 3 + 1, 3) || CASE WHEN substr(date((COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch'), 1, 4) <> substr(?4, 1, 4) THEN ' ' || substr(date((COALESCE(updated_at, created_at) + ?3) / 1000, 'unixepoch'), 1, 4) ELSE '' END END AS edited, CASE WHEN ((length(body) - length(replace(body, '- [x]', ''))) / 5) + ((length(body) - length(replace(body, '- [ ]', ''))) / 5) > 0 THEN ((length(body) - length(replace(body, '- [x]', ''))) / 5) || '/' || (((length(body) - length(replace(body, '- [x]', ''))) / 5) + ((length(body) - length(replace(body, '- [ ]', ''))) / 5)) END AS checklist, CASE WHEN (SELECT COUNT(*) FROM notes p WHERE p._deleted IS NULL AND p.pinned = 1) = 0 THEN NULL WHEN pinned = 1 THEN 'Pinned' ELSE 'Notes' END AS section FROM notes WHERE _deleted IS NULL AND (?1 IS NULL OR ?1 = '' OR title LIKE '%' || ?1 || '%' OR body LIKE '%' || ?1 || '%' OR project LIKE '%' || ?1 || '%') AND ((COALESCE(?2, '') = '' AND COALESCE(project, '') <> 'Tasks') OR project = ?2) ORDER BY pinned DESC, COALESCE(updated_at, created_at) DESC LIMIT 300
